import importlib.util, sys, sqlite3, re, collections
sys.path.insert(0,'/home/user/guidebook/scripts'); sys.path.insert(0,'/home/user/guidebook/scripts/research')
S=sys.argv[1]
def load(n,p):
    sp=importlib.util.spec_from_file_location(n,p); m=importlib.util.module_from_spec(sp); sp.loader.exec_module(m); return m
old=load('db_old',S+'/old/db.py'); new=load('db_new',S+'/new/db.py')
con=sqlite3.connect('file:/home/user/guidebook/data/guidebook.db?mode=ro',uri=True)
print([r for r in con.execute("select sql from sqlite_master where name in ('observed_terms','term_aliases')")])
# candidate names: every observed surface form + every EN alias + EN canon
obs=con.execute("select observation_id,surface_form from observed_terms").fetchall()
d=[]
for oid,sf in obs:
    o={t for t,_ in old._near_terms(con,sf)}; n=new._near_terms(con,sf); nn={t for t,_ in n}
    if o!=nn: d.append((oid,sf,[(t,h) for t,h in n if t not in o], sorted(o-nn)))
print('observed surface forms:',len(obs),'whose near set differs:',len(d))
for x in d: print('  ',x)
# EN aliases as proxy candidate names
en=con.execute("select term_id,alias from term_aliases where upper(language)='EN'").fetchall()
d=[]
for tid,al in en:
    o={t for t,_ in old._near_terms(con,al)}; n=new._near_terms(con,al); nn={t for t,_ in n}
    extra=[(t,h) for t,h in n if t not in o and t!=tid]
    if extra: d.append((tid,al,extra))
print('EN aliases:',len(en),'that gain a near match on ANOTHER term via a foreign alias:',len(d))
for x in d[:40]: print('  ',x)
# English-vocabulary tokens inside foreign aliases
envocab=set()
for _,a in en: envocab|=new._name_tokens(a)
for _,a in con.execute('select term_id,canonical_en from terms'): envocab|=new._name_tokens(a)
foreign=con.execute("select term_id,alias,language from term_aliases where upper(language)<>'EN' and attestation<>'model_seed'").fetchall()
hit=collections.defaultdict(list)
for tid,al,lang in foreign:
    toks=new._name_tokens(al)
    if len(toks)>=2:
        for t in toks & envocab:
            # is there an EN name of the same term containing t? 
            hit[t].append((tid,al,lang))
print('English-vocab tokens occurring in multi-token foreign non-seed aliases:',len(hit))
for t,v in sorted(hit.items(), key=lambda kv:-len(kv[1]))[:40]:
    o={x for x,_ in old._near_terms(con,t)}; n={x for x,_ in new._near_terms(con,t)}
    print(f'  {t!r}: foreign aliases {len(v)}  near(old)={len(o)} near(new)={len(n)} newly={sorted(n-o)[:6]} e.g. {v[0]}')
# stemming effect on foreign aliases
st=[(al,lang,sorted(t for t in re.findall(r"\w+",al.casefold()) if len(t)>3 and t.endswith('s'))) for _,al,lang in foreign]
st=[x for x in st if x[2]]
print('foreign non-seed aliases with a token that loses a trailing s:',len(st)); print(st[:30])
